// Native restricted whole-pass selector; input features only at inference.
#define main archived_reducer_main
#include "../../bounded_memory/src/disk_macaulay.cpp"
#undef main
#include <array>
#include <zlib.h>
struct Feature{std::array<U,4>x{};U bytes=24,terms=0,rows=0;};
static Feature feature(const fs::path&p){std::ifstream f(p,std::ios::binary);U n,d;header(f,n,d);Feature z;z.x[0]=n;z.x[1]=d;while(z.rows<64&&f.peek()!=EOF){Row r=read_row(f);z.rows++;z.terms+=r.size();z.bytes+=8+r.size()*8;z.x[2]+=r.size();z.x[3]=std::max(z.x[3],U(r.size()));}return z;}
static std::string slurp(const fs::path&p){std::ifstream f(p);require(bool(f),"open JSON");return std::string(std::istreambuf_iterator<char>(f),{});}
static U field(const std::string&s,const std::string&k){size_t a=s.find("\""+k+"\"");require(a!=std::string::npos,"missing key "+k);a=s.find(':',a)+1;while(a<s.size()&&s[a]==' ')a++;return std::stoull(s.substr(a));}
struct Obs{U visits,reads,writes,proxy;};
static Obs observation(const fs::path&p){auto s=slurp(p);Obs o{field(s,"sparse_entries_visited_by_xor"),field(s,"pivot_read_bytes"),field(s,"pivot_write_bytes"),0};require((o.reads+o.writes)%8==0,"nonword IO");o.proxy=o.visits+(o.reads+o.writes)/8;return o;}
static std::array<U,3> trace(const fs::path&p,U expected){gzFile f=gzopen(p.c_str(),"rb");require(f,"trace open");char line[2048];U sum=0,lines=0,bytes=0;while(gzgets(f,line,sizeof line)){std::string s=line;require(s.back()=='\n',"long trace line");sum+=field(s,"incoming_weight")+field(s,"pivot_weight");bytes+=s.size();lines++;}int err=0;gzerror(f,&err);require(err==Z_OK||err==Z_STREAM_END,"gzip trace read");gzclose(f);require(sum==expected,"trace/result XOR count mismatch");return {sum,lines,bytes};}
static void features_json(const Feature&f){std::cout<<"\"features\":["<<f.x[0]<<","<<f.x[1]<<","<<f.x[2]<<","<<f.x[3]<<"],\"prefix_rows\":"<<f.rows<<",\"prefix_terms_visited\":"<<f.terms<<",\"prefix_bytes_read\":"<<f.bytes;}
int main(int argc,char**argv){try{require(argc>=2,"train manifest | apply model rows | compare result first min");std::string op=argv[1];if(op=="train"){
 require(argc==3,"train args");std::ifstream in(argv[2]);std::vector<Feature> f;std::vector<std::array<Obs,2>> o;U trace_bytes=0,trace_rows=0,label_charge=0,feature_bytes=0,feature_terms=0;std::string name,r,a,at,b,bt;while(in>>name>>r>>a>>at>>b>>bt){f.push_back(feature(r));o.push_back({observation(a),observation(b)});feature_bytes+=f.back().bytes;feature_terms+=f.back().terms;auto ta=trace(at,o.back()[0].visits),tb=trace(bt,o.back()[1].visits);trace_bytes+=ta[2]+tb[2];trace_rows+=ta[1]+tb[1];label_charge+=o.back()[0].proxy+o.back()[1].proxy;}
 require(f.size()==2,"exactly two frozen training shapes");U evals=0,comparisons=0,best=UINT64_MAX;int bf=-1,bl=0,br=0;U threshold=0;auto trial=[&](int feat,U t,int l,int rr){U loss=0;for(size_t i=0;i<f.size();i++){int choice=feat<0?l:(f[i].x[feat]<=t?l:rr);loss+=o[i][choice].proxy;evals++;if(feat>=0)comparisons++;}if(loss<best){best=loss;bf=feat;bl=l;br=rr;threshold=t;}};trial(-1,0,0,0);trial(-1,0,1,1);for(int k=0;k<4;k++){U lo=std::min(f[0].x[k],f[1].x[k]),hi=std::max(f[0].x[k],f[1].x[k]);if(lo==hi)continue;U t=lo+(hi-lo)/2;for(int l=0;l<2;l++)for(int rr=0;rr<2;rr++)trial(k,t,l,rr);}
 std::cout<<"{\"schema\":\"whole-pass-selector-model/v1\",\"feature_index\":"<<bf<<",\"threshold\":"<<threshold<<",\"left_policy\":"<<bl<<",\"right_policy\":"<<br<<",\"policy_encoding\":[\"first\",\"min-weight\"],\"constant\":"<<(bf<0?"true":"false")<<",\"training_selected_proxy\":"<<best<<",\"label_acquisition_proxy\":"<<label_charge<<",\"trace_bytes_read_uncompressed\":"<<trace_bytes<<",\"trace_records_parsed\":"<<trace_rows<<",\"trace_scalar_fields_parsed\":"<<trace_rows*2<<",\"training_prefix_bytes_read\":"<<feature_bytes<<",\"training_prefix_terms_visited\":"<<feature_terms<<",\"candidate_sample_evaluations\":"<<evals<<",\"threshold_comparisons\":"<<comparisons<<",\"training_rows\":[";for(size_t i=0;i<f.size();i++){if(i)std::cout<<",";std::cout<<"{";features_json(f[i]);std::cout<<",\"first_proxy\":"<<o[i][0].proxy<<",\"min_weight_proxy\":"<<o[i][1].proxy<<"}";}std::cout<<"]}\n";return 0;
 }if(op=="apply"){require(argc==4,"apply args");auto start=std::chrono::steady_clock::now();std::string m=slurp(argv[2]);Feature f=feature(argv[3]);bool constant=m.find("\"constant\":true")!=std::string::npos;U policy=field(m,"left_policy"),comparisons=0;if(!constant){U k=field(m,"feature_index");require(k<4,"feature index");comparisons=1;if(f.x[k]>field(m,"threshold"))policy=field(m,"right_policy");}require(policy<2,"policy label");auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-start).count();std::cout<<"{";features_json(f);std::cout<<",\"policy\":\""<<(policy?"min-weight":"first")<<"\",\"threshold_comparisons\":"<<comparisons<<",\"model_output_decisions\":1,\"selection_elapsed_ns_shared_host\":"<<ns<<"}\n";return 0;}
 if(op=="compare"){require(argc==5,"compare args");auto selected=observation(argv[2]),a=observation(argv[3]),b=observation(argv[4]);std::cout<<"{\"fresh_proxy\":"<<selected.proxy<<",\"archived_first_proxy\":"<<a.proxy<<",\"archived_min_weight_proxy\":"<<b.proxy<<",\"fresh_matches_archived_min_weight_count_vector\":"<<((selected.visits==b.visits&&selected.reads==b.reads&&selected.writes==b.writes)?"true":"false")<<"}\n";return 0;}throw std::runtime_error("unknown op");}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}
